import{_ as t,o,c as r,j as a,a as s}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/19-生物学研究的真相.md","filePath":"books/attached/19-生物学研究的真相.md","lastUpdated":1794316978000}'),n={name:"books/attached/19-生物学研究的真相.md"};function l(d,e,c,_,i,p){return o(),r("div",null,[...e[0]||(e[0]=[a("h3",{id:"生物学研究的真相",tabindex:"-1"},[s("生物学研究的真相 "),a("a",{class:"header-anchor",href:"#生物学研究的真相","aria-label":'Permalink to "生物学研究的真相"'},"​")],-1),a("p",null,"许多研究表明，当我们开始依恋对方，两个人就会建立一种生理上的关联。我们与伴侣之间在血压、心率、呼吸，甚至血液中的荷尔蒙分泌都会互相影响。从此我们就不再是独立的个体了。因此，那些时下流行的心理学理论所秉持的保持独立的主张，在生理学的角度就难以立足了。事实就是，彼此的依赖是在生理上客观存在的，人们根本没得选择。",-1),a("p",null,"来自弗吉尼亚大学情感神经科学实验室的詹姆斯·科恩（James Coan）博士，其主持的一项研究尤其证明了这种效应。研究表明，我们处于亲密关系和泛泛之交情感状态之下的神经机制，控制着不同的情绪反应。他与理查德·戴维森（Richard Davidson）、希拉里·谢弗（Hilary schaeffer）共同合作了这项研究，他用功能性核磁共振成像（fMRI）技术，对一组已婚妇女的大脑进行了扫描。在扫描过程中，科恩博士与他的同事们模拟出一个压力场景，告知她们说，大脑会受到一阵微弱的电击。",-1),a("p",null,"通常情况下，人们的下丘脑会在压力情境下变得更为活跃。而在实验中，这些女性在独自等待电流刺激时，她们的下丘脑会开始活跃。而接下来让她们握着陌生人的手等待电流刺激，扫描结果却显示，这次她们的下丘脑活动减弱了。那么，当她们握着自己丈夫的手等待电击时，会发生什么呢？接下来的事情非常出人意料——她们的紧张感几乎消失了。不仅如此，那些之前报告自己婚姻非常美满的女性，对于伴侣握着自己手时所感到的安心程度也更明显。不过这一点，我们放到后面再说。",-1),a("p",null,"这项研究结果显示，两个处于亲密关系中的人，他们真的会影响到对方的心理和情绪。每当彼此互相靠近，陪伴对方时，能够削弱原本的紧张感觉。连基本的生理反应都这么明显地受到对方的影响，我们又凭什么去强迫伴侣之间必须要相互独立呢？",-1),a("p",null,"而我们例子的主人公卡伦，正是本能地感觉到了来自伴侣掌心的温度，会在紧张环境下为自己带来力量。然而不幸的是，随后她就进入了那种公认的误区，自认为她的直觉是一种懦弱的表现，并且为之羞愧不已。",-1)])])}const m=t(n,[["render",l]]);export{h as __pageData,m as default};
